// ============================================================
// MineraAI → ComfyUI RunPod — FÁBRICA MISTA (imagem + vídeo)
// Recebe roteiro cena a cena e gera kit completo
// ============================================================
const job = $input.first().json.body || $input.first().json;
const product = job.product || 'produto';
const style = job.style || 'ugc';
const duration = job.duration || 6;
const roteiro = job.roteiro || {};
const promptsExtras = job.prompts || [];

const STYLE_PREFIX = {
  ugc: 'foto amadora UGC, luz natural, iPhone, casa real, autêntico, ', 
  dark: 'dark aesthetic, moody, cinematic, misterioso, ', 
  cinematic: 'cinematic lighting, 8k, ultra detailed, professional, ', 
  produto: 'product photography, studio lighting, commercial, high detail, ', 
  anime: 'anime style, vibrant, detailed illustration, '
};
const prefix = STYLE_PREFIX[style] || STYLE_PREFIX.ugc;

// Roteiro: se não veio, cria a partir do prompt
let cenas = roteiro.cenas || [];
if (!cenas.length) {
  const base = job.prompt || product;
  cenas = [
    { nome: 'GANCHO', descricao: `Hook forte para ${product}`, prompt: `${prefix} close-up reação surpresa, ${product} desfocado fundo, hook visual, 9:16`, duracao: '2s' },
    { nome: 'PROBLEMA', descricao: `Dor que ${product} resolve`, prompt: `${prefix} pessoa com problema, bagunça, antes do produto, 9:16`, duracao: '2s' },
    { nome: 'DEMO', descricao: `Demo real ${product}`, prompt: `${prefix} ${base}, demonstração uso real, cozinha real, mão segurando, 9:16 vertical`, duracao: '3s' },
    { nome: 'CTA', descricao: `CTA`, prompt: `${prefix} ${product} com overlay CTA 'LINK NA BIO', destaque, 9:16`, duracao: '1s' }
  ];
}

// Prompts de imagem por cena
const imagemPrompts = cenas.map(c => `${c.prompt || c.descricao || ''}, ${product}, estilo ${style}, 9:16 vertical, alta qualidade`.slice(0,1200));
// Prompt de vídeo geral
const videoPrompt = `${prefix}${job.prompt || ''}, Produto: ${product}, roteiro: ${roteiro.hook || ''} ${roteiro.narracao || ''}, ${cenas.map(c => c.descricao).join('. ')}, vertical 9:16, movimento suave, 6s`.slice(0,1500);

// Workflow MISTO: 4 imagens + 1 video (AnimateDiff)
const seedBase = Math.floor(Math.random()*1e12);
const workflow = {};

// Loaders
workflow['1'] = { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: 'sd_xl_base_1.0.safetensors' } };
workflow['2'] = { class_type: 'EmptyLatentImage', inputs: { width: 768, height: 1344, batch_size: 1 } };
workflow['7'] = { class_type: 'CLIPTextEncode', inputs: { text: "low quality, blurry, watermark, logo, text, deformed, extra limbs, cartoon, drawing", clip: ['1',1] } };
workflow['40'] = { class_type: 'ADE_LoadAnimateDiffModel', inputs: { model_name: 'mm_sd_v15_v2.ckpt' } };
workflow['41'] = { class_type: 'ADE_AnimateDiffLoaderWithContext', inputs: { model: ['1',0], motion_model: ['40',0], beta_schedule: 'sqrt_linear (AnimateDiff)', context_length: 16, context_stride: 1, context_overlap: 4 } };
workflow['42'] = { class_type: 'EmptyLatentImage', inputs: { width: 512, height: 768, batch_size: 16 } };

// Imagens por cena
imagemPrompts.forEach((p, idx) => {
  const idBase = 10 + idx*10;
  workflow[`${idBase}`] = { class_type: 'CLIPTextEncode', inputs: { text: p, clip: ['1',1] } };
  workflow[`${idBase+1}`] = { class_type: 'KSampler', inputs: { seed: seedBase+idx, steps: 28, cfg: 7.5, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['1',0], positive: [`${idBase}`,0], negative: ['7',0], latent_image: ['2',0] } };
  workflow[`${idBase+2}`] = { class_type: 'VAEDecode', inputs: { samples: [`${idBase+1}`,0], vae: ['1',2] } };
  workflow[`${idBase+3}`] = { class_type: 'SaveImage', inputs: { filename_prefix: `mineraai/misto_${job.job_id}_cena_${idx}_${cenas[idx]?.nome || 'img'}`, images: [`${idBase+2}`,0] } };
});

// Vídeo geral
workflow['90'] = { class_type: 'CLIPTextEncode', inputs: { text: videoPrompt, clip: ['1',1] } };
workflow['91'] = { class_type: 'KSampler', inputs: { seed: seedBase+100, steps: 25, cfg: 7.0, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['41',0], positive: ['90',0], negative: ['7',0], latent_image: ['42',0] } };
workflow['92'] = { class_type: 'VAEDecode', inputs: { samples: ['91',0], vae: ['1',2] } };
workflow['93'] = { class_type: 'VHS_VideoCombine', inputs: { images: ['92',0], frame_rate: 8, loop_count: 0, filename_prefix: `mineraai/misto_${job.job_id}_video`, format: 'video/h264-mp4', pix_fmt: 'yuv420p', crf: 19 } };

return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, product, cenas, imagemPrompts, videoPrompt, input: { workflow } } }];

// Extrai video + imagens do output misto
const r = $input.first().json;
const out = r.output || {};
let video_url = '';
let images = [];
const job = $('Montar Workflow Misto').first().json;

if (typeof out === 'object' && !Array.isArray(out)) {
  video_url = out.video_url || out.video || '';
  if (out.images) {
    images = out.images.map((img, idx) => typeof img === 'string' ? { url: img, prompt: job.imagemPrompts[idx] || '', cena: job.cenas[idx]?.nome || `cena_${idx}` } : { url: img.url || img.filename || '', prompt: job.imagemPrompts[idx] || img.prompt || '', cena: job.cenas[idx]?.nome || '' });
  }
  // fallback procura urls
  if (!video_url) {
    const s = JSON.stringify(out);
    const vMatch = s.match(/https?:\/\/[^"\s]+\.mp4[^"\s]*/);
    if (vMatch) video_url = vMatch[0];
  }
  if (!images.length) {
    const s = JSON.stringify(out);
    const iMatches = s.match(/https?:\/\/[^"\s]+\.(png|jpg|jpeg|webp)[^"\s]*/g);
    if (iMatches) images = iMatches.map((u, idx) => ({ url: u, prompt: job.imagemPrompts[idx] || '', cena: job.cenas[idx]?.nome || '' }));
  }
} else if (Array.isArray(out)) {
  for (const item of out) {
    if (typeof item === 'string') {
      if (item.includes('.mp4')) video_url = item;
      else images.push({ url: item, prompt: '', cena: '' });
    } else if (item.url) {
      if (item.url.includes('.mp4')) video_url = item.url;
      else images.push({ url: item.url, prompt: item.prompt || '' });
    }
  }
}

// Se ainda vazio, usa mensagem
if (!video_url && !images.length) {
  video_url = out.message || '';
}

return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, video_url, images, cenas: job.cenas, cost_usd: r.cost || null } }];
